-- Row-level-security regression checks. Run against a local database:
--   psql "$(npx supabase status -o env | grep DB_URL | cut -d= -f2- | tr -d '"')" -v ON_ERROR_STOP=1 -f supabase/tests/rls.sql
-- Everything happens inside a transaction that is rolled back.
begin;

insert into public.lots (id, label) values ('t-1', 'Test lot 1'), ('t-2', 'Test lot 2') on conflict do nothing;
insert into auth.users (id, email, aud, role) values
  ('00000000-0000-0000-0000-0000000000a1', 'rls-resident@example.test', 'authenticated', 'authenticated'),
  ('00000000-0000-0000-0000-0000000000a2', 'rls-neighbor@example.test', 'authenticated', 'authenticated'),
  ('00000000-0000-0000-0000-0000000000a3', 'rls-pending@example.test', 'authenticated', 'authenticated');
update public.profiles set status = 'approved', lot_id = 't-1' where id = '00000000-0000-0000-0000-0000000000a1';
update public.profiles set status = 'approved', lot_id = 't-2' where id = '00000000-0000-0000-0000-0000000000a2';
insert into public.ballots (id, title, opens_at, closes_at, status) values ('00000000-0000-0000-0000-0000000000b1', 'RLS test', now() - interval '1 hour', now() + interval '1 hour', 'published');
insert into public.ballot_questions (id, ballot_id, prompt, max_choices, options) values ('00000000-0000-0000-0000-0000000000c1', '00000000-0000-0000-0000-0000000000b1', 'Q', 1, '[{"id":"yes","label":"Yes"},{"id":"no","label":"No"}]');

create function pg_temp.as_user(uid text) returns void language sql as
$$ select set_config('request.jwt.claims', json_build_object('sub', uid, 'role', 'authenticated')::text, true), set_config('role', 'authenticated', true) $$;
create function pg_temp.expect_error(sql text, what text) returns void language plpgsql as
$$ begin
  begin execute sql; exception when others then raise notice 'ok   - % (%)', what, sqlerrm; return; end;
  raise exception 'FAIL - % was allowed', what;
end $$;
create function pg_temp.expect(cond boolean, what text) returns void language plpgsql as
$$ begin if cond then raise notice 'ok   - %', what; else raise exception 'FAIL - %', what; end if; end $$;
grant execute on all functions in schema pg_temp to authenticated;

-- Resident
select pg_temp.as_user('00000000-0000-0000-0000-0000000000a1');
select pg_temp.expect((select count(*) from public.profiles) = 1, 'resident sees only their own profile');
select pg_temp.expect_error($$update public.profiles set role = 'admin' where id = '00000000-0000-0000-0000-0000000000a1'$$, 'resident cannot make themselves admin');
select pg_temp.expect_error($$update public.profiles set lot_id = 't-2' where id = '00000000-0000-0000-0000-0000000000a1'$$, 'resident cannot change their lot');
update public.profiles set role = 'admin' where id = '00000000-0000-0000-0000-0000000000a2';
select pg_temp.expect((select role from public.profiles where id = '00000000-0000-0000-0000-0000000000a1') = 'resident', 'resident cannot edit another profile');
select pg_temp.expect((select count(*) from public.lot_facts) >= 0, 'approved member may read lot facts');
select pg_temp.expect_error($$select * from public.ballot_votes$$, 'nobody can read individual votes');
select pg_temp.expect_error($$insert into public.ballot_receipts (ballot_id, lot_id) values ('00000000-0000-0000-0000-0000000000b1', 't-2')$$, 'receipts cannot be forged');
select public.cast_ballot('00000000-0000-0000-0000-0000000000b1', '{"00000000-0000-0000-0000-0000000000c1":["yes"]}');
select pg_temp.expect_error($$select public.cast_ballot('00000000-0000-0000-0000-0000000000b1', '{"00000000-0000-0000-0000-0000000000c1":["no"]}')$$, 'a lot cannot vote twice');
select pg_temp.expect_error($$select * from public.ballot_results('00000000-0000-0000-0000-0000000000b1')$$, 'members cannot see results while voting is open');
select pg_temp.expect_error($$insert into public.form_submissions (reference, form_type, user_id, lot_id, data) values ('ARC', 'arc_request', '00000000-0000-0000-0000-0000000000a2', 't-2', '{}')$$, 'cannot submit a request as someone else');
insert into public.form_submissions (reference, form_type, user_id, lot_id, data) values ('ARC', 'arc_request', '00000000-0000-0000-0000-0000000000a1', 't-1', '{}');
select pg_temp.expect((select reference ~ '^ARC-\d{4}-\d{4}$' from public.form_submissions where user_id = '00000000-0000-0000-0000-0000000000a1'), 'reference number is generated by the database');
update public.form_submissions set status = 'approved' where user_id = '00000000-0000-0000-0000-0000000000a1';
select pg_temp.expect((select status from public.form_submissions where user_id = '00000000-0000-0000-0000-0000000000a1') = 'submitted', 'resident cannot approve their own request');
select pg_temp.expect_error($$insert into public.documents (title, category, storage_path, file_name, mime_type) values ('x', 'notice', 'x', 'x', 'x')$$, 'resident cannot add documents');
select pg_temp.expect_error($$insert into public.audit_log (action) values ('forged')$$, 'audit log cannot be written by users');

-- Neighbor
select pg_temp.as_user('00000000-0000-0000-0000-0000000000a2');
select pg_temp.expect((select count(*) from public.form_submissions) = 0, 'neighbor cannot see another member''s request');
select pg_temp.expect((select count(*) from public.ballot_receipts) = 0, 'neighbor cannot see whether another lot voted');

-- Signed in but not approved
select pg_temp.as_user('00000000-0000-0000-0000-0000000000a3');
select pg_temp.expect((select count(*) from public.lot_facts) = 0, 'pending account cannot read owner data');
select pg_temp.expect((select count(*) from public.documents where visibility <> 'public') = 0, 'pending account cannot list member documents');
select pg_temp.expect_error($$select public.cast_ballot('00000000-0000-0000-0000-0000000000b1', '{}')$$, 'pending account cannot vote');
select pg_temp.expect((select count(*) from public.member_directory()) = 0, 'pending account gets an empty directory');

-- Dues: an owner sees only their own lot; only staff can record payments.
reset role;
insert into public.dues_periods (year, due_date) values (2099, '2099-03-01');
insert into public.dues (year, lot_id, amount) values (2099, 't-1', 550), (2099, 't-2', 400);
select pg_temp.as_user('00000000-0000-0000-0000-0000000000a1');
select pg_temp.expect((select count(*) from public.dues where year = 2099) = 1, 'resident sees only their own lot''s dues');
select pg_temp.expect((select lot_id from public.dues where year = 2099) = 't-1', 'the dues row a resident sees is their own');
update public.dues set paid_on = current_date, method = 'check' where year = 2099;
select pg_temp.expect((select paid_on from public.dues where year = 2099) is null, 'resident cannot mark dues as paid');
select pg_temp.expect_error($$insert into public.dues (year, lot_id, amount) values (2099, 't-1', 1)$$, 'resident cannot add dues rows');
select pg_temp.expect_error($$insert into public.dues_periods (year, due_date) values (2098, '2098-03-01')$$, 'resident cannot open a dues year');
select pg_temp.as_user('00000000-0000-0000-0000-0000000000a3');
select pg_temp.expect((select count(*) from public.dues) = 0, 'pending account cannot read dues');
select pg_temp.expect((select count(*) from public.dues_periods) = 0, 'pending account cannot read dues years');
reset role;
update public.profiles set role = 'board' where id = '00000000-0000-0000-0000-0000000000a2';
select pg_temp.as_user('00000000-0000-0000-0000-0000000000a2');
select pg_temp.expect((select count(*) from public.dues where year = 2099) = 2, 'board member sees every lot''s dues');
update public.dues set paid_on = current_date, method = 'check' where year = 2099 and lot_id = 't-1';
select pg_temp.expect((select paid_on from public.dues where year = 2099 and lot_id = 't-1') is not null, 'board member can record a payment');
delete from public.dues_periods where year = 2099;
select pg_temp.expect((select count(*) from public.dues_periods where year = 2099) = 1, 'board member cannot delete a dues year');

-- Hardening: results stay hidden while voting is open, even for staff; published ballots are frozen.
select pg_temp.expect_error($$select * from public.ballot_results('00000000-0000-0000-0000-0000000000b1')$$, 'board member cannot read a live tally');
select pg_temp.expect_error($$update public.ballots set status = 'draft' where id = '00000000-0000-0000-0000-0000000000b1'$$, 'published ballot cannot return to draft');
reset role;
insert into public.form_submissions (id, reference, form_type, user_id, lot_id, data) values ('00000000-0000-0000-0000-0000000000d1', 'ARC', 'arc_request', '00000000-0000-0000-0000-0000000000a1', 't-1', '{}');
select pg_temp.as_user('00000000-0000-0000-0000-0000000000a1');
select pg_temp.expect_error($$insert into public.submission_files (submission_id, storage_path, file_name, mime_type, size_bytes) values ('00000000-0000-0000-0000-0000000000d1', 'someone-else/secret.pdf', 'x.pdf', 'application/pdf', 10)$$, 'attachment row cannot point outside the request folder');
select pg_temp.expect_error($$insert into public.submission_events (submission_id, actor, kind, status) values ('00000000-0000-0000-0000-0000000000d1', '00000000-0000-0000-0000-0000000000a1', 'comment', 'approved')$$, 'member cannot attach a status to a comment');
select pg_temp.expect_error($$insert into public.form_submissions (reference, form_type, user_id, lot_id, data) values ('ARC', 'arc_request', '00000000-0000-0000-0000-0000000000a1', 't-1', jsonb_build_object('x', (select string_agg(md5(i::text), '') from generate_series(1, 20000) i)))$$, 'oversized request data is rejected');

rollback;
